// Package commitreveal implements a minimal commit-reveal scheme.
//
// A commitment is the hex-encoded SHA-256 of the exact byte string
//
//	salt + ":" + payload
//
// The payload stays secret until the revealer publishes payload and salt;
// anyone can then recompute the commitment and check it matches the value
// that was committed earlier. The salt keeps short or guessable payloads
// from being brute-forced against a bare hash of the payload alone.
//
// The package is pure and stateless: it is safe to import from any realm.
package commitreveal

import (
	"crypto/sha256"
	"encoding/hex"
)

// Commit returns the commitment for payload under salt: the lowercase
// hex encoding of SHA-256(salt + ":" + payload).
func Commit(payload string, salt string) string {
	sum := sha256.Sum256([]byte(salt + ":" + payload))
	return hex.EncodeToString(sum[:])
}

// IsCommitment reports whether s has the canonical commitment format:
// exactly 64 lowercase hexadecimal characters.
func IsCommitment(s string) bool {
	if len(s) != 64 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return false
		}
	}
	return true
}

// Verify reports whether commitment is well-formed and equals the
// commitment recomputed from payload and salt.
func Verify(commitment string, payload string, salt string) bool {
	if !IsCommitment(commitment) {
		return false
	}
	return Commit(payload, salt) == commitment
}

package commitreveal

import "testing"

// Known vector, computed off-chain with:
//
//	printf 's3cret:hello world' | sha256sum
const (
	testPayload    = "hello world"
	testSalt       = "s3cret"
	testCommitment = "b5165d20616e37ff3b4c84c2ba2914ced11bf2df7755a8876f2b22d30fb2409a"
)

func TestCommitKnownVector(t *testing.T) {
	got := Commit(testPayload, testSalt)
	if got != testCommitment {
		t.Fatalf("Commit(%q, %q) = %q, want %q", testPayload, testSalt, got, testCommitment)
	}
}

func TestCommitFormat(t *testing.T) {
	if !IsCommitment(Commit("anything", "else")) {
		t.Fatal("Commit output must satisfy IsCommitment")
	}
	if !IsCommitment(testCommitment) {
		t.Fatal("known vector must satisfy IsCommitment")
	}
}

func TestVerifyHappyPath(t *testing.T) {
	if !Verify(testCommitment, testPayload, testSalt) {
		t.Fatal("Verify must accept the correct payload and salt")
	}
	c := Commit("a secret message", "random-salt-123")
	if !Verify(c, "a secret message", "random-salt-123") {
		t.Fatal("Verify must accept a freshly computed commitment")
	}
}

func TestVerifyWrongPayload(t *testing.T) {
	if Verify(testCommitment, "hello worle", testSalt) {
		t.Fatal("Verify must reject a wrong payload")
	}
	if Verify(testCommitment, "", testSalt) {
		t.Fatal("Verify must reject an empty payload")
	}
}

func TestVerifyWrongSalt(t *testing.T) {
	if Verify(testCommitment, testPayload, "s3creT") {
		t.Fatal("Verify must reject a wrong salt")
	}
	if Verify(testCommitment, testPayload, "") {
		t.Fatal("Verify must reject an empty salt")
	}
}

func TestMalformedCommitments(t *testing.T) {
	bad := []string{
		"",                                                                 // empty
		"b5165d20616e37ff3b4c84c2ba2914ced11bf2df7755a8876f2b22d30fb2409",   // 63 chars
		"b5165d20616e37ff3b4c84c2ba2914ced11bf2df7755a8876f2b22d30fb2409aa", // 65 chars
		"B5165D20616E37FF3B4C84C2BA2914CED11BF2DF7755A8876F2B22D30FB2409A", // uppercase
		"g5165d20616e37ff3b4c84c2ba2914ced11bf2df7755a8876f2b22d30fb2409a", // non-hex char
		" b5165d20616e37ff3b4c84c2ba2914ced11bf2df7755a8876f2b22d30fb2409a", // leading space
	}
	for _, s := range bad {
		if IsCommitment(s) {
			t.Fatalf("IsCommitment(%q) = true, want false", s)
		}
		if Verify(s, testPayload, testSalt) {
			t.Fatalf("Verify(%q, ...) = true, want false", s)
		}
	}
}

package sealedpost

import (
	"chain/runtime"
	"strconv"
	"strings"
)

// realmWebPath is this realm's path as served by gnoweb; render arguments
// (the string handed to Render) are appended after a ":".
const realmWebPath = "/r/g1gu8mdvjg8l5wj2ytknhs7pmyu0rmeclyvvlsd8/sealedpost"

// Render serves the realm's gnoweb pages:
//
//	""               home: every capsule, newest first
//	"capsule/<id>"   a single capsule in full
func Render(path string) string {
	path = strings.Trim(path, "/")
	if path == "" {
		return renderHome()
	}
	if strings.HasPrefix(path, "capsule/") {
		id, err := strconv.ParseUint(strings.TrimPrefix(path, "capsule/"), 10, 64)
		if err != nil || id == 0 || id > uint64(len(capsules)) {
			return "# Sealed Post\n\nCapsule not found.\n\n[Back to all capsules](" + realmWebPath + ")\n"
		}
		return renderCapsule(capsules[id-1])
	}
	return "# Sealed Post\n\nPage not found.\n\n[Back to all capsules](" + realmWebPath + ")\n"
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Sealed Post\n\n")
	b.WriteString("Time capsules for messages to the future. A capsule stores only a title " +
		"and a SHA-256 commitment to a secret message. The message is revealed — and " +
		"cryptographically verified against the commitment — once its unlock block arrives.\n\n")
	b.WriteString("Current block height: " + strconv.FormatInt(runtime.ChainHeight(), 10) + "\n\n")
	if len(capsules) == 0 {
		b.WriteString("No capsules yet. Seal the first one!\n")
		return b.String()
	}
	b.WriteString("## Capsules\n\n")
	for i := len(capsules) - 1; i >= 0; i-- {
		b.WriteString(capsuleSummary(capsules[i]))
	}
	return b.String()
}

func capsuleSummary(c *Capsule) string {
	var b strings.Builder
	b.WriteString("### [" + strconv.FormatUint(c.ID, 10) + ". " + c.Title + "](" +
		realmWebPath + ":capsule/" + strconv.FormatUint(c.ID, 10) + ")\n\n")
	b.WriteString("By " + c.Author.String())
	if c.Recipient != address("") {
		b.WriteString(", for " + c.Recipient.String())
	}
	b.WriteString("\n\n")
	if c.Revealed {
		b.WriteString("> " + c.RevealedText + "\n\n")
	} else {
		remaining := c.UnlockHeight - runtime.ChainHeight()
		if remaining < 0 {
			remaining = 0
		}
		b.WriteString("Sealed until block " + strconv.FormatInt(c.UnlockHeight, 10) +
			" (" + strconv.FormatInt(remaining, 10) + " blocks to go).\n\n")
	}
	return b.String()
}

func renderCapsule(c *Capsule) string {
	var b strings.Builder
	b.WriteString("# " + c.Title + "\n\n")
	b.WriteString("- Capsule: " + strconv.FormatUint(c.ID, 10) + "\n")
	b.WriteString("- Author: " + c.Author.String() + "\n")
	if c.Recipient != address("") {
		b.WriteString("- For: " + c.Recipient.String() + "\n")
	}
	b.WriteString("- Sealed at block: " + strconv.FormatInt(c.CreatedHeight, 10) + "\n")
	b.WriteString("- Unlock block: " + strconv.FormatInt(c.UnlockHeight, 10) + "\n")
	b.WriteString("- Commitment: `" + c.Commitment + "`\n\n")
	if c.Revealed {
		b.WriteString("## Revealed message\n\n")
		b.WriteString("> " + c.RevealedText + "\n")
	} else {
		remaining := c.UnlockHeight - runtime.ChainHeight()
		if remaining < 0 {
			remaining = 0
		}
		b.WriteString("This capsule is still sealed. " +
			strconv.FormatInt(remaining, 10) + " blocks to go.\n")
	}
	b.WriteString("\n[Back to all capsules](" + realmWebPath + ")\n")
	return b.String()
}

// Package sealedpost is a time-capsule realm built on commit-reveal.
//
// A capsule stores only a public title and a SHA-256 commitment to a
// secret message (see gno.land/p/g1gu8mdvjg8l5wj2ytknhs7pmyu0rmeclyvvlsd8/commitreveal). The message itself
// stays off-chain and secret until the capsule's unlock height is reached;
// then anyone who knows the message and its salt can reveal it, and the
// realm verifies the reveal against the commitment before publishing the
// text. Knowledge of payload+salt is the authorization to reveal: there is
// deliberately no caller check in Reveal, because the commitment makes a
// forged reveal impossible and lets a recipient (or anyone the author
// trusted with the secret) perform the reveal.
package sealedpost

import (
	"chain/runtime"
	"strconv"

	"gno.land/p/g1gu8mdvjg8l5wj2ytknhs7pmyu0rmeclyvvlsd8/commitreveal"
)

const (
	maxTitleLen   = 80
	maxPayloadLen = 2000
)

// Capsule is one sealed message. IDs are assigned sequentially from 1 and
// the capsule with ID n lives at capsules[n-1].
type Capsule struct {
	ID            uint64
	Author        address
	Recipient     address // zero address = not addressed to anyone; a public "addressed to" label only
	Title         string  // public
	Commitment    string  // commitreveal commitment to the secret payload
	UnlockHeight  int64   // first height at which Reveal is accepted
	CreatedHeight int64
	Revealed      bool
	RevealedText  string // empty until revealed
}

var capsules []*Capsule

// Seal creates a new capsule committing to a secret payload and returns
// the new capsule's ID as a decimal string.
//
// The commitment must be commitreveal.Commit(payload, salt), computed
// off-chain by the author; the payload itself is never sent here.
// unlockHeight must be strictly in the future. recipient is optional:
// empty means "no recipient", otherwise it must be a valid bech32 address
// and is stored as a public label only (it grants no privileges).
func Seal(cur realm, title string, commitment string, unlockHeight int64, recipient string) string {
	author := cur.Previous().Address()

	if len(title) > maxTitleLen {
		panic("sealedpost: title too long (max 80 characters)")
	}
	if !commitreveal.IsCommitment(commitment) {
		panic("sealedpost: invalid commitment: want 64 lowercase hex characters (sha256)")
	}
	now := runtime.ChainHeight()
	if unlockHeight <= now {
		panic("sealedpost: unlock height must be greater than the current height")
	}
	var recip address
	if recipient != "" {
		recip = address(recipient)
		if !recip.IsValid() {
			panic("sealedpost: invalid recipient address")
		}
	}

	c := &Capsule{
		ID:            uint64(len(capsules)) + 1,
		Author:        author,
		Recipient:     recip,
		Title:         title,
		Commitment:    commitment,
		UnlockHeight:  unlockHeight,
		CreatedHeight: now,
	}
	capsules = append(capsules, c)
	return strconv.FormatUint(c.ID, 10)
}

// Reveal publishes the secret payload of capsule id. It is accepted only
// once the current height has reached the capsule's unlock height, and
// only if payload+salt hash to the stored commitment. There is no caller
// restriction: knowing payload+salt is the authorization, and the
// commitment check makes the reveal unforgeable.
func Reveal(_ realm, id uint64, payload string, salt string) string {
	c := capsuleByID(id)
	if c.Revealed {
		panic("sealedpost: capsule already revealed")
	}
	if runtime.ChainHeight() < c.UnlockHeight {
		panic("sealedpost: capsule is still sealed: unlock height not reached")
	}
	if len(payload) > maxPayloadLen {
		panic("sealedpost: payload too long (max 2000 characters)")
	}
	if !commitreveal.Verify(c.Commitment, payload, salt) {
		panic("sealedpost: reveal failed: payload and salt do not match the commitment")
	}
	c.Revealed = true
	c.RevealedText = payload
	return "capsule " + strconv.FormatUint(c.ID, 10) + " revealed"
}

// capsuleByID returns the capsule with the given ID, panicking if there
// is none.
func capsuleByID(id uint64) *Capsule {
	if id == 0 || id > uint64(len(capsules)) {
		panic("sealedpost: capsule not found")
	}
	return capsules[id-1]
}

package sealedpost

import (
	"crypto/bech32"
	"strings"
	"testing"

	"gno.land/p/g1gu8mdvjg8l5wj2ytknhs7pmyu0rmeclyvvlsd8/commitreveal"
)

// testAddr derives a deterministic valid bech32 address from a short
// name (same scheme as gno.land/p/nt/testutils, replicated here so the
// tests stay self-contained within this workspace).
func testAddr(name string) address {
	raw := []byte("____________________")
	copy(raw[:], name)
	converted, err := bech32.ConvertBits(raw, 8, 5, true)
	if err != nil {
		panic(err)
	}
	enc, err := bech32.Encode("g", converted)
	if err != nil {
		panic(err)
	}
	return address(enc)
}

var (
	alice = testAddr("alice")
	bob   = testAddr("bob")
)

// mustPanic fails the test if f does not panic. Panics raised inside a
// realm function invoked through cross() surface as cross-realm aborts,
// which recover() cannot catch; the revive builtin catches them instead
// (same approach as gno.land/p/nt/uassert).
func mustPanic(t *testing.T, what string, f func()) {
	t.Helper()
	if abort := revive(f); abort == nil {
		t.Fatalf("expected panic (%s), got none", what)
	}
}

// reset clears all realm state and sets the chain height. Note: the
// caller is NOT set here — testing.SetRealm only takes effect on the
// realm chain captured by the calling frame, so every test must call
// testing.SetRealm(testing.NewUserRealm(alice)) in its own body (the
// pattern used by the official examples). Chain height, in contrast, is
// machine-global and can be set from this helper.
func reset(height int64) {
	capsules = nil
	testing.SetHeight(height)
}

const (
	secretPayload = "hello future"
	secretSalt    = "pepper"
)

func TestSealAndRevealHappyPath(cur realm, t *testing.T) {
	reset(100)
	testing.SetRealm(testing.NewUserRealm(alice))
	commitment := commitreveal.Commit(secretPayload, secretSalt)

	id := Seal(cross(cur), "First capsule", commitment, 150, "")
	if id != "1" {
		t.Fatalf("Seal returned id %q, want %q", id, "1")
	}
	if len(capsules) != 1 {
		t.Fatalf("got %d capsules, want 1", len(capsules))
	}
	c := capsules[0]
	if c.Author != alice {
		t.Fatalf("author = %s, want %s", c.Author, alice)
	}
	if c.Recipient != address("") {
		t.Fatalf("recipient = %s, want zero address", c.Recipient)
	}
	if c.CreatedHeight != 100 || c.UnlockHeight != 150 {
		t.Fatalf("heights = created %d unlock %d, want 100/150", c.CreatedHeight, c.UnlockHeight)
	}
	if c.Revealed {
		t.Fatal("capsule must start unrevealed")
	}

	// Exactly at the unlock height the reveal is accepted.
	testing.SetHeight(150)
	res := Reveal(cross(cur), 1, secretPayload, secretSalt)
	if !strings.Contains(res, "revealed") {
		t.Fatalf("Reveal returned %q", res)
	}
	if !c.Revealed || c.RevealedText != secretPayload {
		t.Fatalf("after reveal: revealed=%v text=%q", c.Revealed, c.RevealedText)
	}

	// Render shows the revealed text on both pages.
	if out := Render(""); !strings.Contains(out, "First capsule") || !strings.Contains(out, secretPayload) {
		t.Fatalf("home render missing title or revealed text:\n%s", out)
	}
	if out := Render("capsule/1"); !strings.Contains(out, secretPayload) {
		t.Fatalf("capsule render missing revealed text:\n%s", out)
	}
}

