)

func TestVault(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(alice))

	fp := "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
	doc := "invoice-101.pdf"

	res := RegisterInvoice(cross(cur), fp, doc)
