	}
}

package miner

import (
	"errors"
	"math"
)

// Compact codec of a State: one short string instead of a tree of objects,
// so a realm can keep a farm in a single string field (one stored value
// instead of an object per card, rig and history entry). Decode(Encode(st))
// gives back the same state exactly: every float64 bit for bit (also -0,
// NaN and ±Inf), every int, string, slot and card.
//
// Format (version "A"):
//
//	A <header> ; <rigs> ; <cards> ; <offers> ; <history>
//
//   - header: 13 numbers joined by ",": wallet, pool, last, lastClaim,
//     seasonStart, room, nextId, watch, mined, value, spentElec, born,
//     season (the JSON order).
//   - rigs: each rig is "/" followed by its slots as runs joined by ".":
//     "x" is one slot with card id x (0 = empty), "x+k" is x, x+1, …, x+k
//     (for x = 0: k+1 empty slots). A rig without slots is a bare "/".
//   - cards, ascending ids: each run is "/" id "." t "." oc, then "*" for
//     the RGB edition, then "+k" when the next k ids are the same card
//     (same t, oc and RGB).
//   - offers: each entry is "/" and the offer key (e.g. "12:0").
//   - history: each entry is "/" season "." value "." mined "." badge "."
//     room "." event (badge and event "" for none).
//
// Numbers are base 36 (0-9a-z) with an optional "-". A float64 that is an
// integer below 2^53 in magnitude is written as that integer; any other
// float64 is "~" followed by its IEEE-754 bits in base 36. Strings (offer
// keys, badge and event names) must not contain any of , ; / . — Encode
// panics on one that does; the game never makes such a string.
//
// A typical farm takes well under 1 KB: an 80-card data-center farm whose
// rigs each run one model is about 300 bytes.

const codecVersion = 'A'

var errCodec = errors.New("bad farm encoding")

// Encode returns the compact form of st (see the format above).
func Encode(st *State) string {
	// A byte slice and append: cheaper in gas than a strings.Builder's
	// method calls.
	b := make([]byte, 0, 256)
	b = append(b, codecVersion)
	b = encFloat(b, st.Wallet)
	b = append(b, ',')
	b = encFloat(b, st.Pool)
	b = append(b, ',')
	b = encInt(b, st.Last)
	b = append(b, ',')
	b = encInt(b, st.LastClaim)
	b = append(b, ',')
	b = encInt(b, st.SeasonStart)
	b = append(b, ',')
	b = encInt(b, int64(st.Room))
	b = append(b, ',')
	b = encInt(b, int64(st.NextID))
	b = append(b, ',')
	b = encInt(b, int64(st.Watch))
	b = append(b, ',')
	b = encFloat(b, st.Mined)
	b = append(b, ',')
	b = encFloat(b, st.Value)
	b = append(b, ',')
	b = encFloat(b, st.SpentElec)
	b = append(b, ',')
	b = encInt(b, st.Born)
	b = append(b, ',')
	b = encInt(b, int64(st.Season))

	b = append(b, ';')
	for _, rig := range st.Rigs {
		b = append(b, '/')
		n := len(rig)
		for i := 0; i < n; {
			x := rig[i]
			k := 0
			if x == 0 {
				for i+k+1 < n && rig[i+k+1] == 0 {
					k++
				}
			} else {
				for i+k+1 < n && rig[i+k+1] == x+k+1 {
					k++
				}
			}
			if i > 0 {
				b = append(b, '.')
			}
			b = encInt(b, int64(x))
			if k > 0 {
				b = append(b, '+')
				b = encInt(b, int64(k))
			}
			i += k + 1
		}
	}

	b = append(b, ';')
	ids := st.CardIDs()
	n := len(ids)
	for i := 0; i < n; {
		id := ids[i]
		c := st.Cards[id]
		k := 0
		for i+k+1 < n && ids[i+k+1] == id+k+1 {
			x := st.Cards[id+k+1]
			if x.T != c.T || x.OC != c.OC || x.RGB != c.RGB {
				break
			}
			k++
		}
		b = append(b, '/')
		b = encInt(b, int64(id))
		b = append(b, '.')
		b = encInt(b, int64(c.T))
		b = append(b, '.')
		b = encInt(b, int64(c.OC))
		if c.RGB {
			b = append(b, '*')
		}
		if k > 0 {
			b = append(b, '+')
			b = encInt(b, int64(k))
		}
		i += k + 1
	}

	b = append(b, ';')
	for _, o := range st.OffersBought {
		b = append(b, '/')
		b = encStr(b, o)
	}

	b = append(b, ';')
	for _, h := range st.History {
		b = append(b, '/')
		b = encInt(b, int64(h.Season))
		b = append(b, '.')
		b = encFloat(b, h.Value)
		b = append(b, '.')
		b = encFloat(b, h.Mined)
		b = append(b, '.')
		b = encStr(b, h.Badge)
		b = append(b, '.')
		b = encInt(b, int64(h.Room))
		b = append(b, '.')
		b = encStr(b, h.Event)
	}
	return string(b)
}

const digits36 = "0123456789abcdefghijklmnopqrstuvwxyz"

func encUint(b []byte, u uint64) []byte {
	if u < 36 {
		return append(b, digits36[u])
	}
	var buf [13]byte
	i := len(buf)
	for u > 0 {
		i--
		buf[i] = digits36[u%36]
		u /= 36
	}
	return append(b, buf[i:]...)
}

func encInt(b []byte, x int64) []byte {
	if x >= 0 {
		return encUint(b, uint64(x))
	}
	b = append(b, '-')
	if x == math.MinInt64 {
		return encUint(b, 1<<63)
	}
	return encUint(b, uint64(-x))
}

// maxExact: integers of smaller magnitude are exact in a float64 and in an
// int64 alike.
const maxExact = 9007199254740992 // 2^53

func encFloat(b []byte, x float64) []byte {
	if x > -maxExact && x < maxExact {
		i := int64(x)
		if float64(i) == x && (i != 0 || math.Float64bits(x) == 0) { // -0 takes the bits form
			return encInt(b, i)
		}
	}
	b = append(b, '~')
	return encUint(b, math.Float64bits(x))
}

func encStr(b []byte, s string) []byte {
	for i, n := 0, len(s); i < n; i++ {
		switch s[i] {
		case ',', ';', '/', '.':
			panic("miner: cannot encode " + s)
		}
	}
	return append(b, s...)
}

// Decode reads a state written by Encode. It returns an error for anything
// Encode cannot produce.
func Decode(s string) (*State, error) {
	n := len(s)
	if n == 0 || s[0] != codecVersion {
		return nil, errCodec
	}
	st := &State{Cards: map[int]*Card{}, Rigs: [][]int{}, History: []HistoryEntry{}, OffersBought: []string{}}
	// header: 13 numbers, then ';'. i < 0 marks an error from here on.
	var h [13]int64
	var hf [13]float64
	i := 1
	for k := 0; k < 13; k++ {
		switch k {
		case 0, 1, 8, 9, 10: // wallet, pool, mined, value, spentElec
			hf[k], i = decFloat(s, i)
		default:
			h[k], i = decInt(s, i)
		}
		sep := byte(',')
		if k == 12 {
			sep = ';'
		}
		if i < 0 || i >= n || s[i] != sep {
			return nil, errCodec
		}
		i++
	}
	st.Wallet, st.Pool, st.Mined, st.Value, st.SpentElec = hf[0], hf[1], hf[8], hf[9], hf[10]
	st.Last, st.LastClaim, st.SeasonStart, st.Born = h[2], h[3], h[4], h[11]
	st.Room, st.NextID, st.Watch, st.Season = int(h[5]), int(h[6]), int(h[7]), int(h[12])

	// rigs
	for i < n && s[i] == '/' {
		i++
		rig := []int{}
		for i < n && s[i] != '/' && s[i] != ';' {
			if len(rig) > 0 {
				if s[i] != '.' {
					return nil, errCodec
				}
				i++
			}
			var x, k int64
			x, i = decInt(s, i)
			if i < 0 {
				return nil, errCodec
			}
			if i < n && s[i] == '+' {
				k, i = decInt(s, i+1)
				if i < 0 || k < 1 || k > 1000 {
					return nil, errCodec
				}
			}
			for j := int64(0); j <= k; j++ {
				if x == 0 {
					rig = append(rig, 0)
				} else {
					rig = append(rig, int(x+j))
				}
			}
		}
		st.Rigs = append(st.Rigs, rig)
	}
	if i >= n || s[i] != ';' {
		return nil, errCodec
	}
	i++

	// cards
	for i < n && s[i] == '/' {
		var id, t, oc, k int64
		id, i = decInt(s, i+1)
		if i < 0 || i >= n || s[i] != '.' {
			return nil, errCodec
		}
		t, i = decInt(s, i+1)
		if i < 0 || i >= n || s[i] != '.' {
			return nil, errCodec
		}
		oc, i = decInt(s, i+1)
		if i < 0 {
			return nil, errCodec
		}
		rgb := false
		if i < n && s[i] == '*' {
			rgb = true
			i++
		}
		if i < n && s[i] == '+' {
			k, i = decInt(s, i+1)
			if i < 0 || k < 1 || k > 100000 {
				return nil, errCodec
			}
		}
		for j := int64(0); j <= k; j++ {
			st.Cards[int(id+j)] = &Card{T: int(t), OC: int(oc), RGB: rgb}
		}
	}
	if i >= n || s[i] != ';' {
		return nil, errCodec
	}
	i++

	// offers
	for i < n && s[i] == '/' {
		var o string
		o, i = decStr(s, i+1)
		st.OffersBought = append(st.OffersBought, o)
	}
	if i >= n || s[i] != ';' {
		return nil, errCodec
	}
	i++

	// history
	for i < n && s[i] == '/' {
		var e HistoryEntry
		var x int64
		x, i = decInt(s, i+1)
		e.Season = int(x)
		if i < 0 || i >= n || s[i] != '.' {
			return nil, errCodec
		}
		e.Value, i = decFloat(s, i+1)
		if i < 0 || i >= n || s[i] != '.' {
			return nil, errCodec
		}
		e.Mined, i = decFloat(s, i+1)
		if i < 0 || i >= n || s[i] != '.' {
			return nil, errCodec
		}
		e.Badge, i = decStr(s, i+1)
		if i >= n || s[i] != '.' {
			return nil, errCodec
		}
		x, i = decInt(s, i+1)
		e.Room = int(x)
		if i < 0 || i >= n || s[i] != '.' {
			return nil, errCodec
		}
		e.Event, i = decStr(s, i+1)
		st.History = append(st.History, e)
	}
	if i != n {
		return nil, errCodec
	}
	return st, nil
}

// decUint reads 1 to 13 base-36 digits at i; next index, or -1.
func decUint(s string, i int) (uint64, int) {
	var u uint64
	j, n := i, len(s) // a len call per byte costs gas
	for j < n {
		c := s[j]
		if c >= '0' && c <= '9' {
			u = u*36 + uint64(c-'0')
		} else if c >= 'a' && c <= 'z' {
			u = u*36 + uint64(c-'a'+10)
		} else {
			break
		}
		j++
	}
	if j == i || j-i > 13 {
		return 0, -1
	}
	return u, j
}

// decInt reads an optional '-' and a number at i; next index, or -1.
func decInt(s string, i int) (int64, int) {
	if i < 0 {
		return 0, -1
	}
	if i < len(s) && s[i] == '-' {
		u, j := decUint(s, i+1)
		if u == 1<<63 {
			return math.MinInt64, j
		}
		return -int64(u), j
	}
	u, j := decUint(s, i)
	return int64(u), j
}

// decFloat reads a float64 at i; next index, or -1.
func decFloat(s string, i int) (float64, int) {
	if i >= 0 && i < len(s) && s[i] == '~' {
		u, j := decUint(s, i+1)
		return math.Float64frombits(u), j
	}
	x, j := decInt(s, i)
	return float64(x), j
}

// decStr reads up to the next separator.
func decStr(s string, i int) (string, int) {
	j, n := i, len(s)
	for j < n {
		switch s[j] {
		case ',', ';', '/', '.':
			return s[i:j], j
		}
		j++
	}
	return s[i:j], j
}

package miner

import (
	"math"
	"strconv"
	"strings"
)

// JSON serialises the state like JSON.stringify of the JS save object:
// same field names and order, empty slots as null, cards keyed by id in
// ascending order, rgb only when true. Numbers use the shortest form that
// reads back to the same float64 (as JS prints them).
func (st *State) JSON() string {
	var b strings.Builder
	b.WriteString(`{"v":`)
	b.WriteString(strconv.Itoa(Version))
	b.WriteString(`,"wallet":`)
	b.WriteString(JSNum(st.Wallet))
	b.WriteString(`,"pool":`)
	b.WriteString(JSNum(st.Pool))
	b.WriteString(`,"last":`)
	b.WriteString(strconv.FormatInt(st.Last, 10))
	b.WriteString(`,"lastClaim":`)
	b.WriteString(strconv.FormatInt(st.LastClaim, 10))
	b.WriteString(`,"seasonStart":`)
	b.WriteString(strconv.FormatInt(st.SeasonStart, 10))
	b.WriteString(`,"room":`)
	b.WriteString(strconv.Itoa(st.Room))
	b.WriteString(`,"rigs":[`)
	for i, rig := range st.Rigs {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteByte('[')
		for k, id := range rig {
			if k > 0 {
				b.WriteByte(',')
			}
			if id == 0 {
				b.WriteString("null")
			} else {
				b.WriteString(strconv.Itoa(id))
			}
		}
		b.WriteByte(']')
	}
	b.WriteString(`],"cards":{`)
	for i, id := range st.CardIDs() {
		c := st.Cards[id]
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteByte('"')
		b.WriteString(strconv.Itoa(id))
		b.WriteString(`":{"t":`)
		b.WriteString(strconv.Itoa(c.T))
		b.WriteString(`,"oc":`)
		b.WriteString(strconv.Itoa(c.OC))
		if c.RGB {
			b.WriteString(`,"rgb":true`)
		}
		b.WriteByte('}')
	}
	b.WriteString(`},"nextId":`)
	b.WriteString(strconv.Itoa(st.NextID))
	b.WriteString(`,"watch":`)
	b.WriteString(strconv.Itoa(st.Watch))
	b.WriteString(`,"mined":`)
	b.WriteString(JSNum(st.Mined))
	b.WriteString(`,"value":`)
	b.WriteString(JSNum(st.Value))
	b.WriteString(`,"spentElec":`)
	b.WriteString(JSNum(st.SpentElec))
	b.WriteString(`,"born":`)
	b.WriteString(strconv.FormatInt(st.Born, 10))
	b.WriteString(`,"season":`)
	b.WriteString(strconv.Itoa(st.Season))
	b.WriteString(`,"history":[`)
	for i, h := range st.History {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(`{"season":`)
		b.WriteString(strconv.Itoa(h.Season))
		b.WriteString(`,"value":`)
		b.WriteString(JSNum(h.Value))
		b.WriteString(`,"mined":`)
		b.WriteString(JSNum(h.Mined))
		b.WriteString(`,"badge":`)
		b.WriteString(jsonStrOrNull(h.Badge))
		b.WriteString(`,"room":`)
		b.WriteString(strconv.Itoa(h.Room))
		b.WriteString(`,"event":`)
		b.WriteString(jsonStrOrNull(h.Event))
		b.WriteByte('}')
	}
	b.WriteString(`],"offersBought":[`)
	for i, x := range st.OffersBought {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(jsonStr(x))
	}
	b.WriteString(`]}`)
	return b.String()
}

// CardIDs returns the ids of the owned cards in ascending order.
func (st *State) CardIDs() []int {
	ids := make([]int, 0, len(st.Cards))
	for id := range st.Cards {
		ids = append(ids, id)
	}
	// insertion sort: the result does not depend on map order
	for i := 1; i < len(ids); i++ {
		x := ids[i]
		j := i
		for j > 0 && ids[j-1] > x {
			ids[j] = ids[j-1]
			j--
		}
		ids[j] = x
	}
	return ids
}

// JSNum formats a float64 like JS Number#toString (as JSON.stringify does):
// shortest round-trip digits, fixed notation for 1e-6 <= |x| < 1e21,
// exponent notation otherwise; NaN and ±Inf become null.
func JSNum(x float64) string {
	if math.IsNaN(x) || math.IsInf(x, 0) {
		return "null"
	}
	if x == 0 {
		return "0"
	}
	a := math.Abs(x)
	if a >= 1e-6 && a < 1e21 {
		return strconv.FormatFloat(x, 'f', -1, 64)
	}
	s := strconv.FormatFloat(x, 'e', -1, 64)
	// Go writes e-07 / e+21; JS writes e-7 / e+21.
	i := strings.IndexByte(s, 'e')
	mant, exp := s[:i], s[i+1:]
	sign := exp[:1]
	digits := strings.TrimLeft(exp[1:], "0")
	if digits == "" {
		digits = "0"
	}
	return mant + "e" + sign + digits
}

func jsonStrOrNull(s string) string {
	if s == "" {
		return "null"
	}
	return jsonStr(s)
}

func jsonStr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"':
			b.WriteString(`\"`)
		case c == '\\':
			b.WriteString(`\\`)
		case c < 0x20:
			const hexd = "0123456789abcdef"
			b.WriteString(`\u00`)
			b.WriteByte(hexd[c>>4])
			b.WriteByte(hexd[c&15])
		default:
			b.WriteByte(c)
		}
	}
	b.WriteByte('"')
	return b.String()
}

package miner

import (
	"strconv"

	"gno.land/p/nt/avl/v0"
)

// Rank badges (Sapphire and Diamond) of a season with many players, as an
// on-chain realm gives them. The JS game (and BadgeOf) uses fixed value
// thresholds for every badge; a shared season instead ranks its results:
//
//   - A result is a farm's season value, rounded (JSRound), as written to
//     its history entry.
//   - N is the number of results of at least Copper (100,000): farms that
//     only joined or barely played cannot create rank slots.
//   - Only results of at least Pearl (3,300,000) can get a rank badge.
//     Below Pearl the fixed thresholds apply (Copper … Pearl).
//   - Diamond: every result at or above the Diamond cutoff, the lowest
//     result at which no more than ceil(2%·N) results are at or above it.
//     Sapphire: every other result at or above the Sapphire cutoff, the
//     lowest result at which no more than ceil(5%·N) results (Diamond and
//     Sapphire together) are at or above it. Equal results always get the
//     same badge, so a tie that would overflow the share stays below it:
//     at most 2% (5%) of N qualify, never more.
//
// A Ladder keeps what this needs and no per-player entry: the counts and a
// histogram of the results of at least Pearl (rounded result -> number of
// players with it). Cuts walks the histogram from the top, at most
// ceil(5%·N)+1 entries.

const (
	DiamondPct = 2 // percent of N, rounded up
	RankPct    = 5 // Diamond and Sapphire together
)

var (
	CopperIdx   = badgeIdx("Copper")
	PearlIdx    = badgeIdx("Pearl")
	SapphireIdx = badgeIdx("Sapphire")
	DiamondIdx  = badgeIdx("Diamond")
	copperMinI  = int64(Badges[CopperIdx].Min)
	pearlMinI   = int64(Badges[PearlIdx].Min)
	bandMin     = bandMins() // Min of each badge below Pearl, by index
)

func bandMins() []int64 {
	m := make([]int64, PearlIdx)
	for i := 0; i < PearlIdx; i++ {
		m[i] = int64(Badges[i].Min)
	}
	return m
}

// bandOf is the fixed-threshold badge of a result in [Copper, Pearl).
func bandOf(v int64) int {
	b := CopperIdx
	for i := CopperIdx + 1; i < PearlIdx; i++ {
		if v >= bandMin[i] {
			b = i
		}
	}
	return b
}

func badgeIdx(name string) int {
	for i, b := range Badges {
		if b.Name == name {
			return i
		}
	}
	panic("no badge " + name)
}

// Ladder is one season's results for the rank rule. The zero value is an
// empty ladder. Change it only with Add, Remove and Move.
type Ladder struct {
	Players   int // results recorded, any value
	Counted   int // results of at least Copper: N of the rule
	PearlPlus int // results of at least Pearl
	hist      avl.Tree
	band      []int // results in [Copper, Pearl) by badge index (nil: none yet)
}

// Cuts is the outcome of the rank rule for a ladder: the lowest result
// that gets Diamond and Sapphire (0: nobody), and how many players get
// each.
type Cuts struct {
	Diamond, Sapphire   int64
	NDiamond, NSapphire int
}

// Slots: how many results may get Diamond, and Diamond or Sapphire, when
// n results count (ceil(n·2%), ceil(n·5%)).
func Slots(n int) (d, ds int) {
	return (n*DiamondPct + 99) / 100, (n*RankPct + 99) / 100
}

const ladderMax int64 = 999999999999999 // 15 digits

// ladderKey: fixed-width decimal, so keys sort like the results.
func ladderKey(v int64) string {
	if v > ladderMax {
		v = ladderMax
	}
	s := strconv.FormatInt(v, 10)
	return "000000000000000"[len(s):] + s
}

func keyResult(k string) int64 {
	var v int64
	for i := 0; i < len(k); i++ {
		v = v*10 + int64(k[i]-'0')
	}
	return v
}

// Add records a result.
func (l *Ladder) Add(v int64) {
	l.Players++
	l.count(v, 1)
}

// Remove takes back a result recorded with Add.
func (l *Ladder) Remove(v int64) {
	l.Players--
	l.count(v, -1)
}

// Move changes a recorded result from old to v.
func (l *Ladder) Move(old, v int64) {
	if old == v {
		return
	}
	l.count(old, -1)
	l.count(v, 1)
}

func (l *Ladder) count(v int64, d int) {
	if v < copperMinI {
		return
	}
	l.Counted += d
	if v < pearlMinI {
		if l.band == nil {
			l.band = make([]int, PearlIdx)
		}
		l.band[bandOf(v)] += d
		return
	}
	l.PearlPlus += d
	k := ladderKey(v)
	n := d
	if x := l.hist.Get(k); x != nil {
		n += x.(int)
	}
	if n <= 0 {
		l.hist.Remove(k)
		return
	}
	l.hist.Set(k, n)
}

// Cuts applies the rank rule to the ladder as it is now.
func (l *Ladder) Cuts() Cuts {
	var c Cuts
	d, ds := Slots(l.Counted)
	cum := 0
	l.hist.ReverseIterate("", "", func(k string, x any) bool {
		n := cum + x.(int)
		if n > ds {
			return true
		}
		v := keyResult(k)
		if n <= d {
			c.Diamond = v
			c.NDiamond = n
		}
		c.Sapphire = v
		cum = n
		return false
	})
	if c.Sapphire == c.Diamond {
		c.Sapphire = 0 // nobody between the cutoffs
	} else {
		c.NSapphire = cum - c.NDiamond
	}
	return c
}

// Top calls cb for the best results, best first, at most n distinct ones,
// with the number of players at each; it stops when cb returns true. Only
// results of at least Pearl are kept.
func (l *Ladder) Top(n int, cb func(v int64, players int) bool) {
	l.hist.ReverseIterateByOffset(0, n, func(k string, x any) bool {
		return cb(keyResult(k), x.(int))
	})
}

// Place is where result v stands among the recorded results: ahead, how
// many are better; tied, how many share v's place, v itself included when
// it is recorded. At or above Pearl a place is one result (the histogram
// is exact); below it the ladder keeps only a count per fixed badge, so the
// place is v's badge band (Copper … Topaz), or the results below Copper.
// It walks the histogram entries at or above v (at most the Pearl results).
func (l *Ladder) Place(v int64) (ahead, tied int) {
	if v < copperMinI {
		return l.Counted, l.Players - l.Counted
	}
	if v < pearlMinI {
		b := bandOf(v)
		ahead = l.PearlPlus
		if l.band != nil {
			n := len(l.band)
			for i := b + 1; i < n; i++ {
				ahead += l.band[i]
			}
			tied = l.band[b]
		}
		return ahead, tied
	}
	k := ladderKey(v)
	l.hist.ReverseIterate(k, "", func(key string, x any) bool {
		if key == k {
			tied = x.(int)
		} else {
			ahead += x.(int)
		}
		return false
	})
	return ahead, tied
}

// RankBadge is the badge (index into Badges, -1 for none) of result v
// under the cutoffs c.
func RankBadge(v int64, c Cuts) int {
	if v >= pearlMinI {
		switch {
		case c.Diamond > 0 && v >= c.Diamond:
			return DiamondIdx
		case c.Sapphire > 0 && v >= c.Sapphire:
			return SapphireIdx
		}
		return PearlIdx
	}
	b := -1
	for i := 0; i < PearlIdx; i++ {
		if v >= int64(Badges[i].Min) {
			b = i
		}
	}
	return b
}

package miner

import "math"

// floor is math.Floor, cheaper in gas: math.Floor is interpreted Gno code
// (Modf on the bit pattern), a float->int conversion is one VM op. Exact
// for |x| < 2^52 (every value here); other inputs go to math.Floor.
func floor(x float64) float64 {
	if x > -4503599627370496 && x < 4503599627370496 {
		if x == 0 {
			return x // keep -0
		}
		f := float64(int64(x))
		if f > x {
			f--
		}
		return f
	}
	return math.Floor(x)
}

// modPos is math.Mod(x, m) for 0 <= x < 2^50 and m > 0, exact like fmod:
// q is corrected so that 0 <= x - q*m < m, and that subtraction is exact
// (Sterbenz). Other inputs go to math.Mod.
func modPos(x, m float64) float64 {
	if !(x >= 0 && x < 1125899906842624) {
		return math.Mod(x, m)
	}
	q := floor(x / m)
	r := x - q*m
	if r < 0 {
		r = x - (q-1)*m
	} else if r >= m {
		r = x - (q+1)*m
	}
	return r
}

// jsRound is JS Math.round: the nearest integer, ties toward +Inf.
// x - floor(x) is exact for |x| < 2^52, so this also gets
// 0.49999999999999994 right (unlike floor(x+0.5)).
func jsRound(x float64) float64 {
	f := floor(x)
	if x-f >= 0.5 {
		return f + 1
	}
	return f
}

// JSRound exposes jsRound for callers that must round like the client.
func JSRound(x float64) float64 { return jsRound(x) }

func fmax(a, b float64) float64 {
	if a > b {
		return a
	}
	return b
}

func fmin(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}

// Gas: math.Pow and math.Exp are interpreted Gno code and cost a lot of
// gas. Their results for the small integer inputs the game uses are taken
// once at init from the same functions, so the values stay bit-identical.
const tableSize = 64

func powTable(base float64) []float64 {
	t := make([]float64, tableSize)
	for k := 0; k < tableSize; k++ {
		t[k] = math.Pow(base, float64(k))
	}
	return t
}

var (
	pow2Table      = powTable(2)
	powValueTable  = powTable(cValuePerHalving)
	powGenDisTable = powTable(cGenDiscount)
	powRigTable    = powTable(cRigGrowth)
	launchTable    = genLaunchTable()
)

// fexp is math.Exp, bit for bit, at about a third of the gas: the same
// argument reduction and polynomial (Go's exp, from FreeBSD's e_exp.c), but
// the final Ldexp(y, k) — interpreted bit fiddling — is a multiplication
// by 2^k, which is exact while the result is a normal number. Outside
// -708 < x < 709 (subnormal or overflowing results) and near zero it calls
// math.Exp itself. TestFexp checks the bits against math.Exp.
func fexp(x float64) float64 {
	const (
		ln2Hi    = 6.93147180369123816490e-01
		ln2Lo    = 1.90821492927058770002e-10
		log2e    = 1.44269504088896338700e+00
		nearZero = 1.0 / (1 << 28)
		p1       = 1.66666666666666657415e-01
		p2       = -2.77777777770155933842e-03
		p3       = 6.61375632143793436117e-05
		p4       = -1.65339022054652515390e-06
		p5       = 4.13813679705723846039e-08
	)
	if !(x > -708 && x < 709) || (x > -nearZero && x < nearZero) {
		return math.Exp(x)
	}
	var k int
	if x < 0 {
		k = int(log2e*x - 0.5)
	} else {
		k = int(log2e*x + 0.5)
	}
	hi := x - float64(k)*ln2Hi
	lo := float64(k) * ln2Lo
	r := hi - lo
	t := r * r
	c := r - t*(p1+t*(p2+t*(p3+t*(p4+t*p5))))
	y := 1 - ((lo - (r*c)/(2-c)) - hi)
	return y * math.Float64frombits(uint64(k+1023)<<52)
}

// powInt is math.Pow(base, k) for the bases above, read from table.
func powInt(table []float64, base float64, k int) float64 {
	if k >= 0 && k < len(table) {
		return table[k]
	}
	return math.Pow(base, float64(k))
}

// launchTable[age] = math.Exp(-age / LaunchDays) for integer ages.
func genLaunchTable() []float64 {
	t := make([]float64, tableSize)
	for a := 0; a < tableSize; a++ {
		t[a] = math.Exp(-float64(a) / cLaunchDays)
	}
	return t
}

func launchExp(age float64) float64 {
	if a := int(age); float64(a) == age && a >= 0 && a < len(launchTable) {
		return launchTable[a]
	}
	return fexp(-age / cLaunchDays)
}

// Noise is JS noise(day, salt): a pseudo random number in [-1, 1) that only
// depends on floor(day) and salt, the same for everyone. Bit-exact with the
// JS 32-bit integer math (Math.imul, >>> 0).
func Noise(day float64, salt int) float64 {
	d := int64(floor(day))
	// (floor(day)*374761393 + salt*668265263) >>> 0: exact in a double for
	// the inputs the game uses, then reduced modulo 2^32.
	v := (d*374761393 + int64(salt)*668265263) % 4294967296
	if v < 0 {
		v += 4294967296
	}
	s := uint64(v)
	// Math.imul(s ^ (s >>> 13), 1274126177) >>> 0
	s = ((s ^ (s >> 13)) * 1274126177) & 0xffffffff
	// (s ^ (s >>> 16)) >>> 0
	s = s ^ (s >> 16)
	return float64(s)/4294967296*2 - 1
}

// Epoch is the number of halvings before day (JS epoch).
func Epoch(day float64) int {
	return int(floor(fmax(0, day) / cHalvingDays))
}

// Phase is the position inside the halving cycle, 0..1 (JS phase).
func Phase(day float64) float64 {
	hd := float64(cHalvingDays)
	return modPos(fmax(0, day), hd) / hd
}

// Reward is the block reward on day (JS reward).
func Reward(day float64) float64 {
	return cR0 / powInt(pow2Table, 2, Epoch(day))
}

// NextHalving is the day of the next halving (JS nextHalving).
func NextHalving(day float64) float64 {
	return float64((Epoch(day) + 1) * cHalvingDays)
}

// CurrentGen is the newest released generation on day (JS currentGen).
func CurrentGen(day float64) int {
	e := Epoch(day)
	if e > nSeries-1 {
		return nSeries - 1
	}
	return e
}

// EventOf is JS eventOf(day, season): the event of that season day, if any.
// Each season has its own calendar.
func EventOf(day float64, season int) (Event, bool) {
	fd := floor(day)
	if fd < 2 || fd >= cSeasonDays {
		return Event{}, false
	}
	d := int(fd)
	if d%cHalvingDays == 0 {
		return Event{}, false
	}
	salt := 90 + (season%997)*13
	if Noise(fd, salt) < 0.3 {
		return Event{}, false
	}
	n := nEvents
	idx := int(floor((Noise(fd, salt+1)+1)/2*float64(n))) % n
	ev := Events[idx]
	ev.Day = d
	return ev, true
}

// eventMul returns the event of the day, or the neutral multipliers.
func eventMul(day float64, season int) Event {
	ev, ok := EventOf(day, season)
	if !ok {
		return noEvent
	}
	return ev
}

// NetHash is the network hash power on day (JS netHash).
func NetHash(day float64, season int) float64 {
	return netHashEv(day, eventMul(fmax(0, day), season))
}

func netHashEv(day float64, ev Event) float64 {
	return netHashAt(day, Epoch(day), ev)
}

// netHashAt: ep = Epoch(day) (Epoch already clamps at 0).
func netHashAt(day float64, e int, ev Event) float64 {
	d := fmax(0, day)
	n := cN0 * fexp(cGrowth*d)
	since := d - float64(e*cHalvingDays)
	if e > 0 && since < cCapDays {
		n *= 1 - cCapitulation*(1-since/cCapDays)
	}
	return n * ev.Net
}

// ValueIndex is the BLK value index on day (JS valueIndex).
func ValueIndex(day float64) float64 {
	d := floor(fmax(0, day))
	return powInt(powValueTable, cValuePerHalving, Epoch(d)) * (1 + cValueRun*Phase(d)) * (1 + cValueJitter*Noise(d, 1))
}

// Demand is the card demand multiplier on day (JS demand).
func Demand(day float64) float64 {
	return cDemandLow + cDemandRun*Phase(floor(fmax(0, day)))
}

// Released reports whether model t is on the market on day (JS released).
func Released(t int, day float64) bool {
	return validModel(t) && day >= float64(Models[t-1].Release)
}

// RealPrice is the real (pre value index) price of model t on day
// (JS realPrice). It panics on an unknown model, like JS does.
func RealPrice(t int, day float64, season int) float64 {
	return realPriceEv(t, day, eventMul(floor(fmax(0, day)), season).Price)
}

// realPriceEv is RealPrice with the day's event price multiplier given.
func realPriceEv(t int, day, evPrice float64) float64 {
	c := &Models[t-1]
	d := floor(fmax(0, day))
	age := d - float64(c.Release)
	launch := 1 + cLaunch*launchExp(fmax(0, age))
	behind := CurrentGen(d) - c.Gen
	if behind < 0 {
		behind = 0
	}
	return c.Price * launch * powInt(powGenDisTable, cGenDiscount, behind) * Demand(d) *
		(1 + cJitter*Noise(d, 10+t)) * evPrice
}

// Package miner is the economy of Coblyn, a GPU mining game. It is
// the Gno twin of web/miner/economy.js: the season realm replays each
// player's logged actions with this package, so it must behave exactly like
// the JavaScript the browser runs.
//
// The golden vectors in z_vectors_test.gno are generated from economy.js by
// tools/miner-vectors.mjs. Change a rule in either file and regenerate them.
//
// Conventions kept from the JavaScript:
//   - Time is int64 milliseconds (now, Last, SeasonStart, ...).
//   - Money and value are float64, computed in the same order of operations.
//   - Math.round(x) is jsRound (nearest, ties toward +Inf), Math.floor is
//     math.Floor, `**` is math.Pow, Math.exp is math.Exp.
//   - JS throws Error(msg); here the same msg comes back as an error value.
//     As in JS, actions settle first, so on error the settle has already
//     been applied to the state.
//
// Differences on purpose:
//   - settle and Rates group installed cards by (model, overclock), so the
//     cost of one settle step grows with the number of distinct models, not
//     with the number of cards. Results equal the JS up to float rounding.
//   - Inputs that only crash the JS (unknown model, unknown card id for
//     overclock, unknown offer index) return errors here.
//   - migrate (save versions 1 and 2) and UI helpers are not ported; chain
//     state starts at version 3.
package miner

import "math"

// Token is the in-game currency name (working name).
const Token = "BLK"

// DisplayScale: network and block reward are shown scaled by this factor.
const DisplayScale = 1000

// Version of the state format (JS `v`).
const Version = 3

const (
	Hour int64 = 3600000
	Day  int64 = 24 * Hour
	// Step is the settle step: one hour, the same in JS.
	Step int64 = 60 * 60000
)

// Hot-path copies of the parameters below. Reading a package variable costs
// gas on every access, a constant costs nothing. Every use keeps a variable
// operand next to the constant, so no constant folding changes a result
// (1 + RGBCfg.Premium, for example, is left on the variable).
const (
	cR0           = 5.0
	cHalvingDays  = 7
	cN0           = 150.0
	cGrowth       = 0.07
	cCapitulation = 0.25
	cCapDays      = 3.0
	cSeasonDays   = 28

	cValuePerHalving = 1.8
	cValueRun        = 0.12
	cValueJitter     = 0.03

	cLaunch      = 0.35
	cLaunchDays  = 2.0
	cGenDiscount = 0.82
	cDemandLow   = 0.92
	cDemandRun   = 0.16
	cJitter      = 0.04

	cRigBase   = 400.0
	cRigGrowth = 1.9

	cOCMax  = 3
	cOCMH   = 0.12
	cOCW    = 0.22
	cOCCost = 0.3

	cRGBSellBack = 0.62
	cRGBMinCls   = 2

	cBoostX    = 3.0
	cBoostDays = 5.0
	cBoostFull = 14.0

	nSeries = 4
	nModels = 16
	nEvents = 6
)

// NetParams is JS NET.
type NetParams struct {
	R0           float64 // block reward (BLK / block), 1 block = 1 min
	HalvingDays  int
	N0           float64 // network hash at day 0 (MH/s)
	Growth       float64 // growth per day
	Capitulation float64 // share of the network that leaves after a halving
	CapDays      float64 // days to recover from the capitulation
	SeasonDays   int
}

var Net = NetParams{R0: cR0, HalvingDays: cHalvingDays, N0: cN0, Growth: cGrowth, Capitulation: cCapitulation, CapDays: cCapDays, SeasonDays: cSeasonDays}

// ValueParams is JS VALUE (the BLK value index).
type ValueParams struct{ PerHalving, Run, Jitter float64 }

var ValueCfg = ValueParams{PerHalving: cValuePerHalving, Run: cValueRun, Jitter: cValueJitter}

// MarketParams is JS MARKET.
type MarketParams struct {
	Launch, LaunchDays, GenDiscount, DemandLow, DemandRun, Jitter float64
}

var Market = MarketParams{Launch: cLaunch, LaunchDays: cLaunchDays, GenDiscount: cGenDiscount, DemandLow: cDemandLow, DemandRun: cDemandRun, Jitter: cJitter}

// SeriesInfo is one entry of JS SERIES (one card generation).
type SeriesInfo struct {
	Name  string
	Color int
}

var Series = []SeriesInfo{
	{"Spark", 0x9fb4c8},
	{"Volt", 0x6fbf8e},
	{"Storm", 0xb48ce0},
	{"Quasar", 0xf2a23a},
}

// ClassInfo is one entry of JS CLASSES.
type ClassInfo struct {
	Name   string
	MH     float64
	Eff    float64
	PPM    float64
	Unlock float64
}

var Classes = []ClassInfo{
	{"Lite", 8, 0.1, 3.1, 0},
	{"Core", 20, 0.15, 5.3, 300},
	{"Pro", 50, 0.22, 9.0, 3000},
	{"Max", 120, 0.32, 15.3, 20000},
}

// Per generation multipliers (JS GEN).
const (
	genMH     = 1.55
	genEff    = 1.6
	genUnlock = 3
)

// Model is one card model (an entry of JS CARDS). T = Gen*4 + Cls + 1.
type Model struct {
	T, Gen, Cls int
	Name        string
	MH          float64
	W           float64
	Price       float64
	Release     int // day the model is released
	Unlock      float64
	Color       int
	VT          int // visual size 1..7
}

// Models is JS CARDS: 16 models, index t-1.
var Models = genModels()

func genModels() []Model {
	out := []Model{}
	for g := 0; g < len(Series); g++ {
		s := Series[g]
		for k := 0; k < len(Classes); k++ {
			c := Classes[k]
			mh := jsRound(c.MH * math.Pow(genMH, float64(g)))
			eff := c.Eff * math.Pow(genEff, float64(g))
			vt := 1 + k + g
			if vt > 7 {
				vt = 7
			}
			out = append(out, Model{
				T:       g*4 + k + 1,
				Gen:     g,
				Cls:     k,
				Name:    s.Name + " " + c.Name,
				MH:      mh,
				W:       jsRound(mh / eff),
				Price:   jsRound(c.PPM * mh),
				Release: g * Net.HalvingDays,
				Unlock:  c.Unlock * math.Pow(genUnlock, float64(g)),
				Color:   s.Color,
				VT:      vt,
			})
		}
	}
	return out
}

// ModelOf is JS card(t); ok is false for an unknown model.
